      dropped_entries: 2,
      first_dropped_at: '2026-08-08T08:00:00.000Z',
      last_dropped_at: '2026-08-08T09:00:00.000Z',
      outcome_counts: { pass: 0, fail: 1, blocked: 0, 'execution-error': 0, recovery: 1 },
    },
