import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import {
  defineClassicAgentWorkflowApplication,
  defineClassicWorkflowApplication,
} from '../../../domains/comet-classic/classic-sdk-application.js';
import { inspectClassicSdkRun } from '../../../domains/comet-classic/classic-sdk-status.js';
import { defineWorkflow } from '../../../domains/engine/runtime.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(
    roots
      .splice(0)
      .map((root) => fs.rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })),
  );
});

it.each(['full', 'hotfix', 'tweak'] as const)(
  'compiles Classic %s Agent checks without changing the legacy definition',
  (profile) => {
    const legacy = defineWorkflow(defineClassicWorkflowApplication(profile).workflow);
    const current = defineWorkflow(defineClassicAgentWorkflowApplication(profile).workflow);
    expect(legacy.version).toBe('1');
    expect(current.version).toBe('2');
    expect(
      Object.keys(current.steps).filter((id) =>
        /\.(build|verify)\.check(?:\.evidence)?$/u.test(id),
      ),
    ).toEqual([]);
    expect(Object.keys(legacy.steps).some((id) => id.endsWith('.verify.check'))).toBe(true);
    expect(current.steps[`${profile}.archive.confirm`]).toMatchObject({ type: 'ask_user' });
  },
);

it('continues a new Classic Run with platform check reports and rejects failed reports before claiming', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-agent-checks-'));
  roots.push(root);
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
  execFileSync(
    'git',
    [
      '-c',
      'user.name=Test',
      '-c',
      'user.email=test@example.invalid',
      'commit',
      '--allow-empty',
      '-m',
      'base',
    ],
    { cwd: root, stdio: 'ignore' },
  );
  const cli = async (...args: string[]) => {
    const result = await runClassicCli([args[0], '--json', ...args.slice(1)], undefined, {
      projectRoot: root,
      invocationCwd: root,
    });
    return JSON.parse(result.stdout!);
  };
  const initialized = await cli('state', 'init', 'demo', 'hotfix', '--isolation', 'current');
  expect(initialized.exitCode, initialized.stderr).toBe(0);
  const dir = path.join(root, 'openspec/changes/demo');
  await fs.writeFile(path.join(dir, 'proposal.md'), '# Proposal\nFix a small defect.\n');
  await fs.writeFile(path.join(dir, 'design.md'), '# Design\nKeep the existing scope.\n');
  await fs.writeFile(path.join(dir, 'tasks.md'), '- [ ] Implement the change\n');
  const preview = await cli('guard', 'demo', 'open');
  const opened = await cli(
    'guard',
    'demo',
    'open',
    '--apply',
    '--approval-hash',
    preview.data.approvalHash,
  );
  expect(opened.exitCode, opened.stderr).toBe(0);
  await fs.writeFile(path.join(dir, 'tasks.md'), '- [x] Implement the change\n');
  await fs.writeFile(
    path.join(root, 'checks.json'),
    JSON.stringify({ checks: [{ name: 'Actual platform command exited 7', result: 'failed' }] }),
  );
  const before = (await inspectClassicSdkRun(root, 'demo')).run;
  const managed = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--',
    process.execPath,
    '-e',
    'process.exit(0)',
  );
  expect(managed.exitCode).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'demo')).run).toEqual(before);
  const rejected = await cli('state', 'complete-build', 'demo', '--checks', 'checks.json');
  expect(rejected.exitCode).not.toBe(0);
  expect((await inspectClassicSdkRun(root, 'demo')).run).toEqual(before);
  await fs.writeFile(
    path.join(root, 'checks.json'),
    JSON.stringify({
      checks: [],
      checksReason: 'No executable check applies to this documentation change.',
    }),
  );
  const completed = await cli('state', 'complete-build', 'demo', '--checks', 'checks.json');
  expect(completed.exitCode, completed.stderr).toBe(0);
  const next = (await inspectClassicSdkRun(root, 'demo')).run;
  expect(next.workflow.version).toBe('2');
  expect(next.actions.some((action) => action.stepId.endsWith('.build.check'))).toBe(false);
  expect(next.actions.find((action) => action.status === 'pending')?.stepId).toBe(
    'hotfix.verify.run',
  );
  expect(completed.data.checksMode).toBe('agent');
  const reportRef = 'docs/superpowers/reports/demo.md';
  await fs.mkdir(path.dirname(path.join(root, reportRef)), { recursive: true });
  await fs.writeFile(
    path.join(root, reportRef),
    '# Verification\nAll scoped acceptance items were reviewed.\n',
  );
  const verified = await cli(
    'guard',
    'demo',
    'verify',
    '--report',
    reportRef,
    '--apply',
    '--checks',
    'checks.json',
  );
  expect(verified.exitCode, verified.stderr).toBe(0);
  const final = (await inspectClassicSdkRun(root, 'demo')).run;
  expect((final.state as { phase: string }).phase).toBe('archive');
  expect(final.actions.some((action) => action.stepId.endsWith('.verify.check'))).toBe(false);
  expect(final.actions.find((action) => action.status === 'pending')?.stepId).toBe(
    'hotfix.archive.prepare',
  );
});

test/domains/comet-native/native-sdk-def:
import { afterEach, expect, it, vi } from 'vitest';
import { readFileSync, promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  createMemoryRuntimeStore,
  createRuntime,
  defineWorkflow,
  hashRuntimeValue,
  type RuntimeValue,
  type WorkflowRun,
} from '../../../domains/engine/runtime.js';
import {
  defineNativeWorkflowApplication,
  nativeSdkApplicationForRun,
} from '../../../domains/comet-native/native-sdk-application.js';
import * as definitions from '../../../domains/comet-native/native-sdk-definition.js';
import { createNativePortableState } from '../../../domains/comet-native/native-portable-state.js';

const application = defineNativeWorkflowApplication();
const currentHash = hashRuntimeValue(defineWorkflow(application.workflow));
const legacy = definitions.nativeSdkLegacyDefinitions(application.workflow);
const reference = (hash: string) => ({ workflow: { id: 'comet-native', version: '1', hash } });
const originalV4 = JSON.parse(
  readFileSync('test/fixtures/native-v4-internal-actions/workflow.json', 'utf8'),
);

it.each(
  definitions
    .nativeSdkLegacyDefinitions(originalV4)
    .map((workflow, index) => ({ workflow, index })),
)(
  'retains the original v4 compatibility definition $index after internal step removal',
  ({ workflow }) => {
    const hash = hashRuntimeValue(defineWorkflow(workflow));
    const selected = nativeSdkApplicationForRun({
      workflow: { id: 'comet-native', version: '4', hash },
    });
    expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
  },
);

it('omits internal result-transfer Actions from new v4 while selecting the original v4 definition', () => {
  const compact = defineNativeWorkflowApplication('4');
  expect(compact.workflow.steps).not.toHaveProperty('shape.revalidate');
  expect(compact.workflow.steps).not.toHaveProperty('verify.revalidate');
  const hash = hashRuntimeValue(defineWorkflow(originalV4));
  const selected = nativeSdkApplicationForRun({
    workflow: { id: 'comet-native', version: '4', hash },
  });
  expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
  expect(selected.workflow.steps).toHaveProperty('shape.revalidate');
  expect(selected.workflow.steps).toHaveProperty('verify.revalidate');
  expect(selected.transitionHandler).not.toBe(compact.transitionHandler);
});

it.each(['pending', 'unknown'] as const)(
  'continues the original v4 Shape Action after compact definitions ship (%s)',
  async (status) => {
    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-v4-original-shape-'));
    try {
      const selected = nativeSdkApplicationForRun({
        workflow: {
          id: 'comet-native',
          version: '4',
          hash: hashRuntimeValue(defineWorkflow(originalV4)),
        },
      });
      const store = createMemoryRuntimeStore<WorkflowRun>();
      const runtime = createRuntime({
        ...selected,
        store,
        workflows: [selected.workflow],
        transitionHandlers: [selected.transitionHandler],
      });
      let run = await runtime.start({
        runId: 'original-v4-shape',
        workflow: { id: 'comet-native', version: '4' },
        input: { name: 'original-v4-shape', artifactRootRef: 'docs' },
        initialState: createNativePortableState({
          name: 'original-v4-shape',
          language: 'en',
        }) as unknown as RuntimeValue,
      });
      const context = { projectRoot: root, requestId: 'original-shape' };
      const proposal = {
        specChanges: [],
        children: null,
        acceptance: [{ id: 'A1', source: 'brief.md', text: 'Preserve the approved behavior.' }],
      };
      const prepared = run.actions.at(-1)!;
      run = await runtime.claim({
        runId: run.runId,
        actionId: prepared.id,
        executorId: 'native-host',
        attempt: prepared.attempt,
        inputHash: prepared.inputHash,
        claimToken: 'original-prepare',
        context,
      });
      run = await runtime.recordOutcome({
        runId: run.runId,
        outcome: {
          actionId: prepared.id,
          attempt: prepared.attempt,
          inputHash: prepared.inputHash,
          claimToken: 'original-prepare',
          outcomeId: 'original-prepare',
          status: 'succeeded',
          output: proposal,
        },
        context,
      });
      const wait = run.waits.at(-1)!;
      run = await runtime.resolveWait({
        runId: run.runId,
        waitId: wait.id,
        proposalHash: wait.proposalHash,
        decisionId: 'original-approval',
        choice: 'approved',
        context,
      });
      const original = run.actions.at(-1)!;
      expect(original.stepId).toBe('shape.revalidate');
      if (status === 'unknown')
        run = await runtime.claim({
          runId: run.runId,
          actionId: original.id,
          executorId: 'native-host',
          attempt: original.attempt,
          inputHash: original.inputHash,
          claimToken: 'original-revalidation',
          context,
        });
      if (status === 'unknown')
        run = await runtime.markUnknown({
          runId: run.runId,
          actionId: original.id,
          attempt: original.attempt,
          reason: 'The original host stopped before submitting the known Shape result.',
        });
      const restored = nativeSdkApplicationForRun(run);
      const reader = createRuntime({
        ...restored,
        store,
        workflows: [restored.workflow],
        transitionHandlers: [restored.transitionHandler],
      });
      if (status === 'pending')
        await reader.claim({
          runId: run.runId,
          actionId: original.id,
          executorId: 'native-host',
          attempt: original.attempt,
          inputHash: original.inputHash,
          claimToken: 'original-revalidation',
          context,
        });
      const recovered = await reader.recordOutcome({
        runId: run.runId,
        outcome: {
          actionId: original.id,
          attempt: original.attempt,
          inputHash: original.inputHash,
          claimToken: 'original-revalidation',
          outcomeId: 'original-revalidation',
          status: 'succeeded',
          output: proposal,
        },
        context,
      });
      expect(recovered.runId).toBe(run.runId);
      expect(recovered.waits).toEqual(run.waits);
      expect(recovered.actions.find((action) => action.id === prepared.id)).toEqual(run.actions[0]);
      expect(recovered.actions.find((action) => action.id === original.id)?.status).toBe(
        'succeeded',
      );
      expect(recovered.actions.at(-1)).toMatchObject({
        stepId: 'build.builder',
        status: 'pending',
      });
      expect(recovered.actions.filter((action) => action.stepId === 'shape.prepare')).toHaveLength(
        1,
      );
    } finally {
      await fs.rm(root, { recursive: true, force: true });
    }
  },
);
it('allows missing Builder raw receipts only for the exact known legacy definitions', () => {
  expect(new Set(legacy.map((workflow) => hashRuntimeValue(defineWorkflow(workflow))))).toEqual(
    new Set(definitions.NATIVE_SDK_LEGACY_BUILDER_INPUT_HASHES),
  );
  expect(definitions.NATIVE_SDK_LEGACY_BUILDER_INPUT_HASHES).not.toContain(currentHash);
});
afterEach(() => vi.restoreAllMocks());

it('recognizes the persisted builtin definition before integration repair recovery', () => {
  const hash = '42c3944e15a25dc0cd179212587049deef1052f47d9c09d2248c2a8de936ec19';
  const selected = nativeSdkApplicationForRun(reference(hash), application);
